function t(k,...a){let s=(I18N[LANG]&&I18N[LANG][k]);if(s==null)s=I18N.en[k];if(s==null)return k;return a.length?s.replace(/\{(\d)\}/g,(_,i)=>a[+i]??''):s;}
// plural: key_1 / key_n (en, fr) — uk also key_2 (2–4) / key_5 (5+, 11–14)
function tn(k,n){const d=I18N[LANG]||I18N.en; let f; if(LANG==='uk'){const m10=n%10,m100=n%100; f=(m10===1&&m100!==11)?'_1':(m10>=2&&m10<=4&&!(m100>=12&&m100<=14))?'_2':'_5';} else f=(n===1||(LANG==='fr'&&n===0))?'_1':'_n';
  let s=d[k+f]??d[k+'_n']??d[k+'_5']??I18N.en[k+f]??I18N.en[k+'_n']; return (s||k).replace('{0}',n);}
