const POI_FR={'Boryspil airport':'aéroport de Boryspil','Zhuliany airport':'aéroport de Jouliany','Hostomel airfield':'aérodrome de Hostomel','Vasylkiv airbase':'base aérienne de Vasylkiv','Bila Tserkva airfield':'aérodrome de Bila Tserkva','Ozerne airbase':'base aérienne d\'Ozerne','Trypillia TPP':'centrale de Trypillia','Kyiv HPP dam':'barrage de Kyiv','Kyiv CHP-5':'centrale Kyiv-5','Kyiv CHP-6':'centrale Kyiv-6','Darnytsia TPP':'centrale de Darnytsia','Chornobyl NPP':'centrale de Tchernobyl'};
const poiName=n=>LANG==='uk'?(POI_UK[n]||n):LANG==='fr'?(POI_FR[n]||n):n;
const BRIDGE_UK={'Pivnichnyi br.':'Північний міст','Podilsko-Vosk. br.':'Подільсько-Воскр. міст','Metro br.':'міст Метро','Paton br.':'міст Патона','Darnytskyi br.':'Дарницький міст','Pivdennyi br.':'Південний міст'};
const bridgeName=n=>LANG==='uk'?(BRIDGE_UK[n]||n):LANG==='fr'?n.replace(' br.',' (pont)'):n;
// a place name from a post: Ukrainian stays Ukrainian in UK, transliterated otherwise
const pn=s=>{s=String(s??'').replace('→ ',''); return LANG==='uk'?s:(typeof translit==='function'?translit(s):s);};
const LOCALE=()=>LANG==='uk'?'uk-UA':LANG==='fr'?'fr-FR':'en-GB';
